"""Validate reviewed runner names and inspect values generated by the actual HCL."""
import json
from pathlib import Path
import re
import subprocess
from tempfile import TemporaryDirectory
import yaml
from kueue_capacity import quantity, requests

ROOT = Path(__file__).resolve().parents[1]
CONFIG = ROOT / 'config/environments/kubernetes/homelab-ci'


def catalog(config_path=CONFIG):
    value = json.loads((config_path / 'runner-catalog.json').read_text())
    if not value:
        raise ValueError('Runner catalog cannot be empty')
    for name, config in value.items():
        if not re.fullmatch(r'homelab-talos(?:-[a-z0-9]+)*', name) or len(name) > 45:
            raise ValueError('Invalid runner name: ' + name)
        if set(config) != {'cpu', 'memory', 'scratch', 'docker'} or type(config['docker']) is not bool:
            raise ValueError('Catalog requires cpu cores, memory/scratch MiB and docker boolean')
        for key, ceiling in [('cpu', 36), ('memory', 163840), ('scratch', 61440)]:
            if type(config[key]) not in (int, float) or not 0 < config[key] <= ceiling:
                raise ValueError('Oversized or invalid runner ' + name + ': ' + key)
            amount = quantity(config[key]) * (1000 if key == 'cpu' else 1)
            if amount != int(amount):
                raise ValueError('Use whole millicores and MiB')
        if config['docker'] and (config['cpu'] < .1 or config['memory'] < 128 or config['scratch'] < 1024):
            raise ValueError('Docker budget must cover initialization peak')
    if value.get('homelab-talos') != dict(cpu=4, memory=16384, scratch=30720, docker=True):
        raise ValueError('Preserve the compatible homelab-talos configuration')
    return value


def rendered_values(config_path=CONFIG):
    # Evaluate the production locals, without backend or provider access.
    with TemporaryDirectory() as directory:
        path = Path(directory)
        source = (ROOT / 'live/kubernetes/homelab-ci/runners.tf').read_text().split('# Preserve')[0]
        (path / 'main.tf').write_text('locals { config = ' + json.dumps(str(config_path)) + ' }\n' + source)
        output = subprocess.check_output(['tofu', '-chdir=' + directory, 'console'], input=b'jsonencode(local.runner_values)\n', timeout=30)
        return json.loads(json.loads(output))


def validate_rendered(values, config_path=CONFIG):
    configurations = catalog(config_path)
    if set(values) != set(configurations):
        raise ValueError('Rendered scale sets differ from catalog')
    for name, config in configurations.items():
        value = values[name]
        if value['runnerScaleSetName'] != name or value['minRunners'] != 0 or 'maxRunners' in value:
            raise ValueError('Scale sets must be disposable and Kueue-limited')
        pod = value['template']
        for resource, expected in [('cpu', quantity(config['cpu'])), ('memory', config['memory'] * 1024**2),
                                   ('ephemeral-storage', config['scratch'] * 1024**2)]:
            if requests(pod, resource) != expected:
                raise ValueError('Whole-Pod aggregate differs from catalog: ' + name + ' ' + resource)
        for container in pod['spec']['containers'] + pod['spec'].get('initContainers', []):
            if container['resources']['requests'] != container['resources']['limits']:
                raise ValueError('Runner requests and limits must match')
        docker = any(c['name'] == 'dind' for c in pod['spec'].get('initContainers', []))
        if docker != config['docker']:
            raise ValueError('Rendered Docker capability differs from catalog')


def validate_workflows():
    configurations = catalog()
    for path in (ROOT / '.github/workflows').glob('*.yml'):
        workflow = yaml.load(path.read_text(), Loader=yaml.BaseLoader)
        for name, job in workflow.get('jobs', {}).items():
            selection = str(job.get('runs-on', ''))
            names = set(re.findall(r'homelab-talos(?:-[a-z0-9]+)*', selection))
            # Inspect the Talos value even when a typo no longer matches our
            # naming prefix. Hosted fallback values remain outside the catalog.
            for encoded in re.findall(r"fromJSON\('([^']+)'\)", selection):
                mapping = json.loads(encoded)
                if isinstance(mapping, dict) and 'talos' in mapping:
                    names.add(mapping['talos'])
            matrix = job.get('strategy', {}).get('matrix', {})
            if 'matrix.runner' in selection:
                names.update(entry['runner'] for entry in matrix.get('include', []) if 'runner' in entry)
                names.update(matrix.get('runner', []))
            for runner in names:
                if runner not in configurations:
                    raise ValueError(f'{path.name}/{name}: unknown runner {runner}; deploy a reviewed catalog entry first')
            requires_docker = job.get('container') or job.get('services') or any(
                step.get('uses', '').startswith(('docker/', 'bridgecrewio/checkov-action@'))
                or step.get('with', {}).get('docker') == 'true' for step in job.get('steps', []))
            if requires_docker and any(not configurations[runner]['docker'] for runner in names):
                raise ValueError(f'{path.name}/{name}: Docker job requires a Docker-enabled catalog configuration')


if __name__ == '__main__':
    validate_workflows()
    validate_rendered(rendered_values())
    print('PASS: catalog names, HCL rendering and whole-Pod CPU/RAM/scratch budgets')
